const services=[['Laundry Service','Daily wear, household laundry with premium care.','laundry','Everyday clothes, carefully washed, dried and neatly folded. Choose laundry by the kilogram or our monthly wash and fold plan.'],['Dry Cleaning','Gentle and professional care for your finest clothes.','dry','Specialist cleaning for delicate garments, formal wear and occasion pieces. Final care and suitability depend on the fabric label.'],['Steam Iron','Crisp, wrinkle-free perfection.','iron','Give shirts, trousers and everyday garments a smooth finish with professional steam pressing.'],['Shoes Cleaning','Deep cleaning for a fresher, newer look.','shoes','Refresh your favourite pairs with cleaning tailored to their material. Share the shoe type when planning your pickup.'],['Alterations & Repairs','Expert stitching and fit adjustments.','repairs','Plan garment alterations, small repairs and fit adjustments. Tell us what needs attention in your pickup address notes.'],['Linen & Upholstery Cleaning','Curtains, bedsheets, sofa & more.','linen','Care for household textiles, from bed linen and curtains to removable upholstery covers.'],['Leather & Suede Cleaning','Specialised care for your leather items.','leather','Dedicated care for leather and suede pieces. Material condition and cleaning suitability need inspection before treatment.'],['Wedding Gown Cleaning & Preservation','Keep your special day memories pristine.','wedding','Thoughtful cleaning and preservation care for treasured wedding garments and delicate detailing.'],['Pillow Refurbishing','Clean, fresh and hygienic pillows.','pillow','Freshen up your bedding with pillow care. Cleaning options depend on the filling and care instructions.']];
const grid=document.querySelector('.services');services.forEach(([title,desc,img,detail])=>{const card=document.createElement('article');card.className='service';card.innerHTML=`<img src="assets/${img}.jpg" alt="${title}" loading="lazy"><div><h3>${title}</h3><p>${desc}</p><button type="button" aria-label="Enquire about ${title}">Enquire →</button></div>`;card.querySelector('button').onclick=()=>openEnquiry(title);grid.append(card)});
const industryNames=['Salons & Spas','Hair Salons and Barber Shops','Automotive Detail & Repair Shops','Assisted Living / Nursing Homes','Hotels & Motels','Local B&Bs','Massage Therapists','Religious Organizations','Sports Teams','Nail Salons','House Cleaning Companies','Pet Groomers','Restaurants & Caterers','Daycare Centers','Therapists and Chiropractors','Athletic Facilities / Gyms'];
const booking=document.querySelector('#booking'),info=document.querySelector('#info'),form=document.querySelector('#booking-form'),select=document.querySelector('#booking-service');[...services.map(s=>s[0]),'Monthly Wash & Fold — ₹350','Laundry Service — ₹299 per kg','Dry Cleaning — ₹140 per item'].forEach(s=>select.add(new Option(s,s)));const dateInput=form.elements.date;const today=new Date();dateInput.min=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;
function openBooking(service){info.close();document.querySelector('#booking-content').hidden=false;document.querySelector('#success').hidden=true;if(service&&[...select.options].some(o=>o.value===service))select.value=service;booking.showModal()}
document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>openBooking());document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>openBooking(b.dataset.plan));document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
function showInfo(title,copy){document.querySelector('#info-title').textContent=title;document.querySelector('#info-copy').textContent=copy;document.querySelector('#info-book').textContent='Plan a Pickup →';document.querySelector('#info-book').onclick=()=>openBooking(title);info.showModal()}
const details={about:['Thoughtful care. Everyday freshness.','MagicKlean brings laundry and dry cleaning to your doorstep in Hyderabad. Explore everyday fabric care, specialist cleaning and convenient pickup options in one place.'],contact:['Let’s make laundry day easier','Serving Hyderabad. You can prepare a pickup request here. A verified phone number, WhatsApp link and live booking connection have not been supplied yet.'],franchise:['Grow with MagicKlean','Interested in bringing MagicKlean to your neighbourhood? Franchise contact details and application information will be available here once supplied by the business.']};document.querySelectorAll('[data-info]').forEach(b=>b.onclick=()=>showInfo(...details[b.dataset.info]));
const enquiry=document.querySelector('#enquiry'),enquiryForm=document.querySelector('#enquiry-form');
function openEnquiry(subject){enquiryForm.reset();document.querySelector('#enquiry-subject').value=subject;enquiryForm.hidden=false;document.querySelector('#enquiry-success').hidden=true;enquiry.showModal()}
enquiryForm.onsubmit=e=>{e.preventDefault();if(!enquiryForm.reportValidity())return;enquiryForm.hidden=true;document.querySelector('#enquiry-success').hidden=false;document.querySelector('#enquiry-done').focus()};document.querySelector('#enquiry-done').onclick=()=>enquiry.close();
document.querySelector('#whatsapp').onclick=()=>{showInfo('Chat on WhatsApp','Welcome to MagicKlean! This sample shows where customers can start a WhatsApp conversation. A business number will be connected when the website goes live.');document.querySelector('#info-book').textContent='Explore services →';document.querySelector('#info-book').onclick=()=>{info.close();document.querySelector('#services').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}};
const industryTrack=document.querySelector('#industries'),industryWindow=document.querySelector('.industry-window');
industryNames.forEach((name,index)=>{const card=document.createElement('article');card.className='industry-card';card.innerHTML=`<img src="assets/business-${index}.jpg" alt="${name}" width="128" height="174" loading="lazy"><div class="industry-card-copy"><h3>${name}</h3><button type="button" aria-label="Enquire about ${name}">Enquire <span aria-hidden="true">→</span></button></div>`;card.querySelector('button').onclick=()=>openEnquiry(name);industryTrack.append(card)});
const originalCards=[...industryTrack.children];originalCards.forEach(card=>{const clone=card.cloneNode(true);clone.setAttribute('aria-hidden','true');clone.querySelector('button').tabIndex=-1;clone.querySelector('button').onclick=()=>openEnquiry(card.querySelector('h3').textContent);industryTrack.append(clone)});
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)'),playButton=document.querySelector('#industry-play');let playing=!reducedMotion.matches,hovering=false,focused=false,dragging=false,inView=false,previousTime=0,offset=0,manualUntil=0;
function updatePlayback(){playButton.setAttribute('aria-pressed',String(playing));playButton.setAttribute('aria-label',playing?'Pause automatic business scrolling':'Play automatic business scrolling');playButton.querySelector('use').setAttribute('href',`assets/icons.svg#${playing?'pause':'play'}`);playButton.querySelector('span').textContent=playing?'Pause':'Play'}
function stopAutoplay(){playing=false;updatePlayback()}
playButton.onclick=()=>{playing=!playing;updatePlayback()};updatePlayback();
industryWindow.addEventListener('mouseenter',()=>hovering=true);industryWindow.addEventListener('mouseleave',()=>hovering=false);industryWindow.addEventListener('focusin',()=>focused=true);industryWindow.addEventListener('focusout',e=>{if(!industryWindow.contains(e.relatedTarget))focused=false});industryWindow.addEventListener('pointerdown',()=>{dragging=true;stopAutoplay()});window.addEventListener('pointerup',()=>dragging=false);industryWindow.addEventListener('wheel',()=>{stopAutoplay()},{passive:true});
new IntersectionObserver(entries=>{inView=entries[0].isIntersecting},{threshold:.05}).observe(industryWindow);
function cycleWidth(){return industryTrack.children[originalCards.length].offsetLeft-industryTrack.children[0].offsetLeft}
function advance(direction){stopAutoplay();const cycle=cycleWidth();if(direction<0&&industryWindow.scrollLeft<originalCards[0].offsetWidth+16)industryWindow.scrollLeft+=cycle;const step=originalCards[0].offsetWidth+16;industryWindow.scrollBy({left:direction*step,behavior:reducedMotion.matches?'instant':'smooth'});manualUntil=performance.now()+650}
document.querySelector('#industry-prev').onclick=()=>advance(-1);document.querySelector('#industry-next').onclick=()=>advance(1);industryWindow.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();advance(e.key==='ArrowLeft'?-1:1)}});
function animateIndustries(time){const elapsed=previousTime?Math.min(time-previousTime,50):0;previousTime=time;if(!document.hidden&&inView&&!dragging&&time>manualUntil){const cycle=cycleWidth();if(cycle>0){if(playing&&!hovering&&!focused){offset=Math.abs(industryWindow.scrollLeft-offset)>2?industryWindow.scrollLeft:offset;offset+=elapsed*.032;offset%=cycle;industryWindow.scrollLeft=offset}else{offset=industryWindow.scrollLeft;if(offset>=cycle){offset-=cycle;industryWindow.scrollLeft=offset}}}}requestAnimationFrame(animateIndustries)}requestAnimationFrame(animateIndustries);reducedMotion.addEventListener('change',e=>{if(e.matches)stopAutoplay()});
form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const request=Object.fromEntries(new FormData(form));try{localStorage.setItem('magicklean-pickup',JSON.stringify(request))}catch{showInfo('Unable to save','Your browser has disabled local storage. Enable storage to save a request on this device.');return}document.querySelector('#booking-content').hidden=true;document.querySelector('#success').hidden=false;document.querySelector('#success-message').textContent=`${request.name}, your ${request.service} request is saved for ${request.date}, ${request.time}.`;};document.querySelector('#done').onclick=()=>booking.close();const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.onclick=()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open)};nav.querySelectorAll('a,button').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const processObserver=new IntersectionObserver(entries=>{if(entries[0].isIntersecting){entries[0].target.classList.add("is-visible");processObserver.disconnect()}},{threshold:.15});processObserver.observe(document.querySelector(".how"));

document.querySelector("#business-quote").onclick=()=>openEnquiry("Commercial Laundry — Business Quote");

const exploreBusinesses=document.querySelector('#explore-businesses'),allBusinesses=document.querySelector('#businesses-all');
originalCards.forEach(source=>{const tile=source.cloneNode(true);tile.classList.add('business-tile');tile.querySelector('button').onclick=()=>openEnquiry(tile.querySelector('h3').textContent);allBusinesses.append(tile)});
exploreBusinesses.onclick=()=>{const expanded=exploreBusinesses.getAttribute('aria-expanded')!=='true';exploreBusinesses.setAttribute('aria-expanded',String(expanded));exploreBusinesses.innerHTML=expanded?'Back to Carousel <span aria-hidden="true">↔</span>':'Explore All Businesses <span aria-hidden="true">↗</span>';allBusinesses.hidden=!expanded;industryWindow.hidden=expanded;document.querySelector('.carousel-note').hidden=expanded;['#industry-prev','#industry-play','#industry-next'].forEach(selector=>document.querySelector(selector).hidden=expanded);if(expanded)stopAutoplay()};
